option.value:
/* Feed central */
.feed {
  display: flex;
  flex-direction: column;
  gap: 1.25rem;
  padding-right: .25rem;
  -webkit-overflow-scrolling: touch;
  min-height: 0;
  align-items: stretch;
  padding-top: 0.5rem;
}

.sidebar-right .map-box { margin-bottom: 1.75rem; }
.sidebar-right #map { height: clamp(160px, 28vh, 220px); }

.post-box { --post-box-h: 72px; }

.share[open] ~ .hecho:first-of-type, /* no aplica estrictamente pero sirve de referencia */
.share + .hecho:first-of-type { margin-top: 0; }

.center-slot > .feed {
  overflow-y: auto;
  overflow-x: hidden;
}

/* Post-box (form de compartir) */
.post-box {
  position: sticky;
  top: calc(var(--header-h,72px) + var(--subnav-h,44px) + 8px);
  z-index: 3;
  border: 1px solid #e5e7eb;
  border-radius: 12px;
  padding: 12px;
  background: #fff;
  display: flex;
  gap: .75rem;
  align-items: center;
}
.post-box input {
  width: 100%;
  padding: .7rem;
  border: 1px solid #e5e7eb;
  background: #f6f7f9;
  border-radius: 8px;
}

.post-icons { display:flex; gap:.4rem; align-items:center; }

/* Hechos (cards) */
.hecho {
  position: relative;
  border: 1px solid #ddd;
  border-radius: 12px;
  padding: 1.2rem;
  box-shadow: 0 2px 6px rgba(0,0,0,0.05);
  background: #fff;
  display: block;
  overflow: visible;
  clear: both;
  margin: 0 0 1rem;
  box-sizing: border-box;
}

.feed .hecho {
  flex: 0 0 auto;
  min-height: 84px;
  width: 100%;
  align-self: stretch;
}
.hecho h2 {
  margin: .5rem 0; font-size: 1.1rem;
  line-height: 1.25;
  margin: .2rem 0 .45rem;
}
.hecho p {
  font-size: .9rem;
  margin: 0 0 .6rem;
  line-height: 1.4;
}
.hecho img {
  display: block;
  max-width: 100%;
  height: auto;
  margin: .5rem 0;
}


.hecho { position: relative; }
.flag-float { z-index: 5; }

.tag { display:inline-block; background:#BDFFDB; color:#000; padding:.2rem .5rem; border-radius:0 0 15px 15px; font-size:.8rem; }

.flag-float { position:absolute; top:15px; right:19px; background:transparent; border:none; cursor:pointer; padding:6px; border-radius:8px; }
.flag-float:hover{ background:#f1f5f9; }

/* Sidebars */
.sidebar, .sidebar-right {
  background: #fff;
  border: 1px solid #e5e7eb;
  border-radius: 12px;
  padding: 12px;
}

/* Map box */
.map-box, .colecciones { border-radius:12px; padding:1rem; border:1px solid #ddd; background:#fff; }
.map-frame { border-radius:10px; overflow:hidden; max-height: 260px; }
#map { width:100%; /* altura reducida y responsive para evitar scroll de página completo */
  height: clamp(120px, 22vh, 200px) !important;
  max-height: 220px;
  min-height: 110px;
}

/* Evitar que la primera card se solape con el post-box sticky (soportando wrappers intermediarios) */
.share + .hecho,
.share ~ .hecho:first-of-type,
.share + * .hecho,
.share ~ * .hecho {
  margin-top: calc(var(--post-box-h, 72px) + 0.75rem);
}

/* Asegurar que el contenedor del mapa no expanda su caja madre inesperadamente */
.sidebar-right .map-box, .sidebar-right .map-frame { max-height: none; }

/* Formularios y campos */
.field label{ font-size:.9rem; font-weight:600; margin-bottom:.25rem; display:block; }
.field input, .field textarea, .field select { width:100%; padding:.7rem .95rem; border:1px solid #d1d5db; border-radius:10px; background:#f6f7f9; font:inherit; }
.field input:focus, .field textarea:focus, .field select:focus { outline:none; border-color:#93c5fd; box-shadow:0 0 0 3px rgba(59,130,246,.15); }

.share-panel { background:var(--ui-card); border:1px solid #e5e7eb; border-top:none; border-radius:0 0 12px 12px; padding:1rem; display:grid; gap:1rem; }
.share-row { display:grid; grid-template-columns: 1fr 320px; gap:.75rem 1rem; }
@media (max-width: 900px) { .share-row { grid-template-columns:1fr; } }

.share-actions { display:flex; justify-content:space-between; align-items:center; gap:.75rem; }

/* Botones */
.btn.small{ padding:.45rem .9rem; font-size:.85rem; }
.btn.chip{ display:inline-flex; align-items:center; gap:.5rem; padding:.55rem .9rem; border-radius:12px; border:1px solid #d1d5db; background:#fff; }

/* Responsive: ajustes puntuales para explore */
@media (max-width: 991.98px) {
  .center-slot { padding-top: .5rem; }
}

img, video { max-width:100%; height:auto; }

.sidebar, .sidebar-right, .center-slot, .feed { min-height: 0; min-width: 0; }


/* ============ Modal ============ */
.modal-overlay[hidden] {
    display: none;
}

.modal-overlay {
    position: fixed;
    inset: 0;
    display: grid;
    place-items: center;
    background: rgba(0, 0, 0, .55);
    z-index: 9999;
}

.auth-modal {
    position: relative;
    width: min(92vw, 480px);
    background: #f6f7f9;
    border-radius: 16px;
    padding: 24px;
    box-shadow: 0 20px 60px rgba(0, 0, 0, .35);
}

.modal-close {
    position: absolute;
    right: 12px;
    top: 10px;
    width: 32px;
    height: 32px;
    border: none;
    background: transparent;
    font-size: 22px;
    font-weight: 700;
    display: grid;
    place-items: center;
    color: #6b7280;
    opacity: .8;
    cursor: pointer;
}

.modal-close,
.modal-close:link,

.modal-close:visited {
    text-decoration: none;
    color: inherit
}

.modal-close:hover {
    color: #374151;
    opacity: 1;
    text-decoration: none;
}

a.btn,
a.modal-close {
    text-decoration: none !important;
}

.btn.primary,
a.btn.primary {
    background: var(--ui-blue);
    color: #fff !important;
    border: 1px solid transparent;
    font-weight: 600;
    text-decoration: none;
}

.btn,
.btn.primary,
.btn.ghost,
a.btn,
a.btn.primary,
a.btn.ghost {
    font-family: 'Poppins', system-ui, -apple-system, Segoe UI, Roboto, "Helvetica Neue", Arial, sans-serif !important;
    font-weight: 600;
}

.target-modal {
    display: none;
}

.target-modal:target {
    display: grid;
}

.upload-form {
    display: grid;
    gap: .8rem;
}

.dropzone {
    position: relative;
    display: grid;
    place-items: center;
    text-align: center;
    gap: .25rem;
    padding: 1.25rem;
    border: 2px dashed #cbd5e1;
    border-radius: 12px;
    background: #f8fafc;
    cursor: pointer;
    color: #0f172a;
}

.dropzone:hover {
    background: #f3f4f6;
}

.dropzone:focus-within {
    outline: 3px solid rgba(59, 130, 246, .25);
    outline-offset: 2px;
}

.dropzone input[type="file"] {
    position: absolute;
    inset: 0;
    opacity: 0;
    cursor: pointer;
}

.upload-actions {
    display: flex;
    justify-content: flex-end;
    gap: .5rem;
}

.post-icons {
    display: flex;
    gap: .4rem;
    align-items: center;
}

.post-icon {
    display: inline-grid;
    place-items: center;
    width: 28px;
    height: 28px;
    border-radius: 6px;
    background: transparent;
    border: none;
    padding: 0;
    cursor: pointer;
}

.post-icon img {
    width: 20px;
    height: 20px;
    display: block;
}

.post-icon:hover,
.post-icon:focus-visible {
    background: #eef2f7;
    outline: none;
}

.overlay-dismiss {
    position: fixed;
    inset: 0;
    position: absolute;
    inset: 0;
    display: block;
    z-index: 0;
}

.success-modal {
    position: relative;
    z-index: 1;
}

.success-modal h2 {
    margin-bottom: .25rem;
}

.success-modal .muted {
    margin: 0 0 .75rem;
}

.upload-modal {
    position: relative;
    z-index: 1;
}

.overlay-dismiss {
    position: absolute;
    inset: 0;
    display: block;
    z-index: 0;
}

.report-modal {
    position: relative;
    z-index: 1;
}

.report-form textarea {
    width: 100%;
    padding: .95rem 1rem;
    border: 1px solid #d1d5db;
    border-radius: 12px;
    background: #f6f7f9;
    font: inherit;
    resize: vertical;
    min-height: 180px;
    transition: border-color .15s ease, box-shadow .15s ease, background-color .15s ease;
    padding-right: 1rem;
    background-image: none !important;
    background-repeat: no-repeat;
}

.report-form textarea:focus {
    outline: none;
    border-color: #93c5fd;
    box-shadow: 0 0 0 3px rgba(59, 130, 246, .15);
}

.report-form textarea:valid {
    border-color: #22c55e;
    background-color: #f0fdf4;
}

.report-form textarea:focus:invalid {
    border-color: #ef4444;
    background-color: #fef2f2;
}

.report-form textarea:valid,
.report-form textarea:focus:invalid {
    background-image: none !important;
    background-color: #fff;
}

.report-form .help {
    margin-top: .35rem;
    font-size: .85rem;
}

.report-form .help.info {
    color: var(--ui-muted);
}

.report-form .error-msg {
    display: none;
    color: #b91c1c;
}

.report-form:has(textarea:focus:invalid) .error-msg {
    display: block;
}

.report-form .submit-report[disabled] {
    opacity: .55;
    cursor: not-allowed;
    filter: saturate(.6);
}

.report-form:has(textarea:valid) .submit-report {
    opacity: 1;
    cursor: pointer;
    filter: none;
}

