/* ============ Share Form (details/summary) ============ */
details.share {
  border-radius: 12px;
}

details.share > summary {
  list-style: none;
  cursor: pointer;
}

details.share > summary::-webkit-details-marker {
  display: none;
}

/* Cuando está abierto, el post-box pierde sus bordes inferiores redondeados */
details.share[open] > summary.post-box {
  border-bottom-left-radius: 0;
  border-bottom-right-radius: 0;
  box-shadow: none;
  border-bottom: 1px solid #e5e7eb;
}

.share-panel {
  background: var(--ui-card, #fff);
  border: 1px solid #e5e7eb;
  border-top: none;
  border-radius: 0 0 12px 12px;
  padding: 1rem;
  display: grid;
  gap: 1rem;
}

/* Deshabilitado por defecto */
.share-panel .submit-btn {
  pointer-events: none;
  opacity: .55;
  cursor: not-allowed;
  filter: saturate(.7);
}

/* Cuando NO hay requeridos inválidos -> habilitar */
.share-panel:not(:has(:required:invalid)) .submit-btn {
  pointer-events: auto;
  opacity: 1;
  cursor: pointer;
  filter: none;
}

